   213		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   214		defer cancel()
   215	
   216		shallowHashes, err := repo.Storer.Shallow()
   217		if err != nil {
   218			return false, fmt.Errorf("read shallow commits: %w", err)
   219		}
   220		if len(shallowHashes) == 0 {
   221			return false, nil
   222		}
   223	
   224		shallowCommits := make(map[string]struct{}, len(shallowHashes))
   225		for _, hash := range shallowHashes {
   226			shallowCommits[hash.String()] = struct{}{}
   227		}
   228		for _, hash := range hashes {
   229			reachesBoundary, err := historyReachesShallowBoundary(ctx, repoPath, hash, shallowCommits)
   230			if err != nil {
   231				return false, err
   232			}
   233			if reachesBoundary {
   234				return true, nil
   235			}
   236		}
   237		return false, nil
   238	}
