   240	func historyReachesShallowBoundary(ctx context.Context, repoPath, hash string, shallowCommits map[string]struct{}) (bool, error) {
   241		cmd := exec.CommandContext(ctx, "git", "rev-list", hash)
   242		cmd.Dir = repoPath
   243		output, err := cmd.Output()
   244		if err != nil {
   245			return false, fmt.Errorf("git rev-list %s failed: %w", hash, err)
   246		}
   247		for _, commitHash := range strings.Fields(string(output)) {
   248			if _, ok := shallowCommits[commitHash]; ok {
   249				return true, nil
   250			}
   251		}
   252		return false, nil
   253	}
