   263	// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
   264	// Returns true if target can reach commit by following parent links.
   265	// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
   266	func IsAncestorOf(ctx context.Context, repo *git.Repository, commit, target plumbing.Hash) bool {
   267		if commit == target {
   268			return true
   269		}
   270	
   271		iter, err := repo.Log(&git.LogOptions{From: target})
   272		if err != nil {
   273			return false
   274		}
   275		defer iter.Close()
   276	
   277		found := false
   278		count := 0
   279		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
   280			if err := ctx.Err(); err != nil {
   281				return err //nolint:wrapcheck // Propagating context cancellation
   282			}
   283			count++
   284			if count > MaxCommitTraversalDepth {
   285				return errStop
   286			}
   287			if c.Hash == commit {
   288				found = true
   289				return errStop
   290			}
   291			return nil
   292		})
   293	
   294		return found
   295	}
