  1282	// countLines counts the number of lines in content.
  1283	func countLines(content []byte) int {
  1284		if len(content) == 0 {
  1285			return 0
  1286		}
  1287		count := 1
  1288		for _, b := range content {
  1289			if b == '\n' {
  1290				count++
  1291			}
  1292		}
  1293		// Don't count trailing newline as extra line
  1294		if len(content) > 0 && content[len(content)-1] == '\n' {
  1295			count--
  1296		}
  1297		return count
  1298	}
