  1300	// computeDiffStats computes added and removed line counts between old and new content.
  1301	// Uses a simple line-based diff algorithm.
  1302	func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
  1303		oldLines := splitLines(oldContent)
  1304		newLines := splitLines(newContent)
  1305	
  1306		// Build a set of old lines with counts
  1307		oldSet := make(map[string]int)
  1308		for _, line := range oldLines {
  1309			oldSet[line]++
  1310		}
  1311	
  1312		// Check which new lines are truly new
  1313		for _, line := range newLines {
  1314			if oldSet[line] > 0 {
  1315				oldSet[line]--
  1316			} else {
  1317				added++
  1318			}
  1319		}
  1320	
  1321		// Remaining old lines are removed
  1322		for _, count := range oldSet {
  1323			removed += count
  1324		}
  1325	
  1326		return added, removed
  1327	}
