  1503	// NOT ignored by .gitignore. This is used to capture the initial state when starting
  1504	// a session, ensuring untracked files present at session start are preserved during rewind.
  1505	// Uses "git ls-files --others --exclude-standard -z" to respect .gitignore rules,
  1506	// avoiding bloated session state from large ignored directories like node_modules/.
  1507	// Returns paths relative to the repository root.
  1508	func collectUntrackedFiles(ctx context.Context) ([]string, error) {
