  1513	
  1514		cmd := exec.CommandContext(ctx, "git", "ls-files", "--others", "--exclude-standard", "-z")
  1515		cmd.Dir = repoRoot
  1516		output, err := cmd.Output()
  1517		if err != nil {
  1518			var exitErr *exec.ExitError
  1519			if errors.As(err, &exitErr) {
  1520				return nil, fmt.Errorf("git ls-files failed: %s: %w", strings.TrimSpace(string(exitErr.Stderr)), err)
  1521			}
  1522			return nil, fmt.Errorf("git ls-files failed: %w", err)
  1523		}
  1524	
  1525		raw := string(output)
  1526		if raw == "" {
  1527			return nil, nil
